#region OrderStationV3
const string VERSION="3.2.10";/**OrderStationV3 Script v3.2.10*Protocol:v3(PMV4 integration)**Requests exchanges from the network.Knows what it has(surplus)*and needs(deficits)via PMV4.Orchestrates cargo transfers when*drones dock.Return-leg cargo is loaded from an explicit manifest*clamped to the drone's hold and split fairly across items.**Version History:*3.2.10-LCDs on subgrids(rotor/hinge/piston)now display;scan not limited to PB grid*3.2.9-LCDs tagged after compile auto-appear(~10s rescan);no RELOAD needed*3.2.8-Fix:docked-drone sweep grabbed the FIRST connected connector,so on a*station with other grids docked it transferred against the wrong grid*(and consumed the exchange before the drone arrived).Sweep now targets*only the exchange's reserved connector.*3.2.7-Fix:exchange timeout was~2.5x cruise ETA(60s floor),shorter than the*real trip(undock prep+cruise+docking approach),so exchanges expired*mid-flight and drones arrived to no match->no load.Now~3 min overhead*+4x ETA,floor~5 min.(Root cause of the surplus/collect loop.)*3.2.6-Diagnostics:log exchange create/remove events(ExchEvt)with timing to*trace why an exchange disappears before the drone docks.*3.2.5-Fix:OS-side docked-drone fallback sweep(CheckDockedArrival)so a*legitimate arrival whose ARRIVED beat the connector connection isn't*permanently skipped by the v3.2.3 dock gate.Restores surplus/collect*(and any)destination loads.Stamps DroneGridName so FinishTransfer clears.*3.2.4-Diagnostics(troubleshooting):persistent arrival decision(here/match),*PULL_COMPLETE branch,and live docked-grid echo on the PB panel.*3.2.3-Fix:ignore arrivals for drones not docked here+only export surplus*for a matched exchange(incl.RecoverState),so a drone returning to its*SupplyStation is no longer loaded with that station's surplus.*Add RequestOnRecompile config;add return-leg diagnostic echo.*3.2.2-Inbound hides a drone once delivered(loading its return leg)*3.2.1-Fix crossed wires:only claim EXCHANGE_ACCEPTED addressed to this station*(older entries:see docs/CargoSystem/VERSIONING.md)*/const string CH_PMV4_INV="PMV4_INVENTORY";const string CH_PMV4_CMD="PMV4_CARGO_CMD";const string CH_PMV4_STAT="PMV4_CARGO_STATUS";const string CH_EXCHANGE_REQ="EXCHANGE_REQUEST";const string CH_EXCHANGE_ACC="EXCHANGE_ACCEPTED";const string CH_EXCHANGE_REJ="EXCHANGE_REJECTED";const string CH_MISSION_COMPLETE="MISSION_COMPLETE";const string CH_SS_INVENTORY="SS_INVENTORY";const string CH_DRONE_ARRIVED="DRONE_ARRIVED";const string CH_SAM="SAM";string stationId="";string supplyStation="";bool exportSurplus=true;string exportPriority="";int reportInterval=300;int reportThreshold=1000;bool requestOnRecompile=false;double droneFillFactor=0.95;HashSet<string>requestCategories=new HashSet<string>();HashSet<string>exportCategories=new HashSet<string>();List<string>locationTags=new List<string>();Dictionary<string,int>manualOrders=new Dictionary<string,int>();Dictionary<string,int>explicitExports=new Dictionary<string,int>();struct ThemeColors{public Color BG,HDR,LBL,VAL,GOOD,WARN,CRIT,DIM;}static ThemeColors ThemeDefault(){return new ThemeColors{BG=new Color(8,8,18),HDR=new Color(0,210,210),LBL=new Color(0,160,160),VAL=new Color(200,200,215),GOOD=new Color(0,210,90),WARN=new Color(255,185,0),CRIT=new Color(255,55,55),DIM=new Color(35,40,50)};}static ThemeColors ThemeMilitary(){return new ThemeColors{BG=new Color(10,12,8),HDR=new Color(180,190,100),LBL=new Color(140,150,80),VAL=new Color(190,195,170),GOOD=new Color(80,180,50),WARN=new Color(220,170,30),CRIT=new Color(220,50,40),DIM=new Color(30,35,25)};}static ThemeColors ThemeHighContrast(){return new ThemeColors{BG=new Color(0,0,0),HDR=new Color(255,255,255),LBL=new Color(200,200,200),VAL=new Color(255,255,255),GOOD=new Color(0,255,0),WARN=new Color(255,255,0),CRIT=new Color(255,0,0),DIM=new Color(60,60,60)};}static ThemeColors ThemeMinimal(){return new ThemeColors{BG=new Color(15,15,20),HDR=new Color(160,165,175),LBL=new Color(120,125,135),VAL=new Color(180,180,190),GOOD=new Color(100,200,120),WARN=new Color(220,180,60),CRIT=new Color(220,70,60),DIM=new Color(40,42,48)};}
static ThemeColors ThemePM(){return new ThemeColors{BG=new Color(0,0,0),HDR=new Color(100,200,255),LBL=new Color(255,200,50),VAL=new Color(200,200,200),GOOD=new Color(80,220,80),WARN=new Color(255,170,0),CRIT=new Color(255,60,60),DIM=new Color(55,55,65)};}struct DisplayLine{public string Text;public string RightText;public Color Col;public Color DotCol;public bool IsSep;public bool IsBanner;public DisplayLine(string text,Color col,string rightText=""){Text=text;Col=col;RightText=rightText;DotCol=default(Color);IsSep=false;IsBanner=false;}}class DisplayGroup{public string Tag;public string[]Sections;public List<IMyTextSurface>Panels=new List<IMyTextSurface>();}List<DisplayLine>_displayLines=new List<DisplayLine>();List<DisplayGroup>_displayGroups=new List<DisplayGroup>();ThemeColors _theme;string _themeName="pm";int _renderGroupIdx=0;int _renderTick=0;int _panelRescanCounter=0;const int PANEL_RESCAN_INTERVAL_TICKS=6;void DL(string text,Color col){_displayLines.Add(new DisplayLine(text,col));}void DLR(string text,Color col,string right){_displayLines.Add(new DisplayLine(text,col,right));}void DLDot(string text,Color col,Color dot,string right=""){_displayLines.Add(new DisplayLine(text,col,right){DotCol=dot});}void DLSep(){_displayLines.Add(new DisplayLine("",_theme.VAL){IsSep=true});}void DLBanner(string title,string subtitle){_displayLines.Add(new DisplayLine(title,_theme.HDR,subtitle){IsBanner=true});}static MySprite Txt(string s,Vector2 pos,Color col,float scale,TextAlignment align=TextAlignment.LEFT)=>new MySprite(SpriteType.TEXT,s,pos,null,col,"Monospace",align,scale);static MySprite Rect(Vector2 center,Vector2 size,Color col)=>new MySprite(SpriteType.TEXTURE,"SquareSimple",center,size,col);static Color SaltColor(Color c,int a)=>new Color(c.R,c.G,c.B,(byte)Math.Min(a,c.A));Dictionary<string,int>pmv4Inventory=new Dictionary<string,int>();Dictionary<string,int>pmv4Surplus=new Dictionary<string,int>();Dictionary<string,int>pmv4Deficit=new Dictionary<string,int>();bool pmv4Connected=false;int pmv4StaleCounter=0;const int PMV4_STALE_TICKS=36;Dictionary<string,int>supplyInventory=new Dictionary<string,int>();HashSet<string>supplyViewCategories=new HashSet<string>();List<string>samConnectors=new List<string>();List<long>samConnectorIds=new List<long>();Dictionary<string,string>connectorReservations=new Dictionary<string,string>();long myGridEntityId=0;class ActiveExchange{public string SupplyStationId;public string DroneId;public string DroneGridName;public string ConnectorName;public Dictionary<string,int>WillBring=new Dictionary<string,int>();public Dictionary<string,int>WillCollect=new Dictionary<string,int>();public int ETASeconds;public double DroneCapacityL;public int AcceptedTick;public int TimeoutTicks;}List<ActiveExchange>activeExchanges=new List<ActiveExchange>();const int PHASE_NONE=0;const int PHASE_PULLING=1;const int PHASE_PUSHING=2;const int TRANSFER_TIMEOUT_TICKS=180;int transferPhase=PHASE_NONE;string transferGridName="";double transferCapacityL=0;int transferStartTick=0;Dictionary<string,int>transferOffer=new Dictionary<string,int>();string transferManifest="";bool transferHasMatch=false;bool outOfStock=false;int outOfStockCounter=0;const int OUT_OF_STOCK_TICKS=18;int reportTickCounter=0;int lastRequestTick=0;bool requestPending=false;const int STARTUP_REQUEST_WINDOW=12;int startupRequestTicks=0;string pendingConnector="";string lastRejectReason="";int missionCooldownEndTick=0;bool validationFailed=false;List<string>validationErrors=new List<string>();StringBuilder statusLog=new StringBuilder();IMyProgrammableBlock pmv4PB=null;int currentTick=0;IMyBroadcastListener pmv4InvListener;IMyBroadcastListener pmv4StatusListener;IMyBroadcastListener exchangeAccListener;IMyBroadcastListener exchangeRejListener;IMyBroadcastListener missionCompleteListener;IMyBroadcastListener supplyInvListener;IMyBroadcastListener droneArrivedListener;IMyBroadcastListener samListener;public Program(){if(string.IsNullOrWhiteSpace(Me.CustomData)){Me.CustomData=GetDefaultConfig();
Echo("=== FIRST-TIME SETUP ===");Echo("Edit CustomData and recompile.");Runtime.UpdateFrequency=UpdateFrequency.None;return;}LoadConfig();FindPMV4();RunValidation();pmv4InvListener=IGC.RegisterBroadcastListener(CH_PMV4_INV);pmv4InvListener.SetMessageCallback("IGC");pmv4StatusListener=IGC.RegisterBroadcastListener(CH_PMV4_STAT);pmv4StatusListener.SetMessageCallback("IGC");exchangeAccListener=IGC.RegisterBroadcastListener(CH_EXCHANGE_ACC);exchangeAccListener.SetMessageCallback("IGC");exchangeRejListener=IGC.RegisterBroadcastListener(CH_EXCHANGE_REJ);exchangeRejListener.SetMessageCallback("IGC");missionCompleteListener=IGC.RegisterBroadcastListener(CH_MISSION_COMPLETE);missionCompleteListener.SetMessageCallback("IGC");supplyInvListener=IGC.RegisterBroadcastListener(CH_SS_INVENTORY);supplyInvListener.SetMessageCallback("IGC");droneArrivedListener=IGC.RegisterBroadcastListener(CH_DRONE_ARRIVED);droneArrivedListener.SetMessageCallback("IGC");samListener=IGC.RegisterBroadcastListener(CH_SAM);samListener.SetMessageCallback(CH_SAM);myGridEntityId=Me.CubeGrid.EntityId;ScanDisplayPanels();Runtime.UpdateFrequency=UpdateFrequency.Update100;RecoverState();if(requestOnRecompile&&activeExchanges.Count==0&&transferPhase==PHASE_NONE)startupRequestTicks=STARTUP_REQUEST_WINDOW;}public void Save(){PersistState();}public void Main(string argument,UpdateType updateSource){bool isUpdate100=(updateSource&UpdateType.Update100)!=0;statusLog.Clear();if(!string.IsNullOrEmpty(argument)){string arg=argument.Trim().ToUpperInvariant();if(arg=="ORDER"){LoadConfig();EvaluateAndSendRequest(true);}else if(arg=="RESET"){Storage="";activeExchanges.Clear();connectorReservations.Clear();transferPhase=PHASE_NONE;transferGridName="";requestPending=false;pendingConnector="";outOfStock=false;Echo("State cleared.");}else if(arg=="RELOAD"){LoadConfig();FindPMV4();ScanDisplayPanels();RunValidation();}}if(validationFailed){foreach(var err in validationErrors)Echo(err);Echo("Fix errors and recompile.");return;}ProcessPMV4Data();ProcessSAMBroadcasts();ProcessExchangeAccepted();ProcessExchangeRejected();ProcessMissionComplete();ProcessSupplyInventory();ProcessDroneArrived();CheckDockedArrival();ProcessCargoStatus();if(isUpdate100){currentTick++;pmv4StaleCounter++;if(pmv4StaleCounter>PMV4_STALE_TICKS)pmv4Connected=false;CheckReservationTimeouts();if(transferPhase!=PHASE_NONE&&currentTick-transferStartTick>TRANSFER_TIMEOUT_TICKS){_exchDbg=$"XFER-TIMEOUT grid={transferGridName} elapsed={currentTick - transferStartTick}c";IGC.SendBroadcastMessage(CH_PMV4_STAT,$"TRANSFER_COMPLETE|{transferGridName}");for(int i=activeExchanges.Count-1;i>=0;i--){if(activeExchanges[i].DroneGridName==transferGridName||activeExchanges[i].DroneId==transferGridName){ReleaseConnector(activeExchanges[i].ConnectorName);activeExchanges.RemoveAt(i);break;}}transferPhase=PHASE_NONE;transferGridName="";PersistState();}if(requestPending){outOfStockCounter++;if(outOfStockCounter>=OUT_OF_STOCK_TICKS){outOfStock=true;requestPending=false;}}if(startupRequestTicks>0){startupRequestTicks--;EvaluateAndSendRequest(false);if(requestPending){startupRequestTicks=0;reportTickCounter=0;}}reportTickCounter++;int ticksNeeded=(int)(reportInterval*0.6);if(ticksNeeded<1)ticksNeeded=1;if(reportTickCounter>=ticksNeeded){reportTickCounter=0;EvaluateAndSendRequest(false);}if(activeExchanges.Count>0||transferPhase!=PHASE_NONE)PersistState();_panelRescanCounter++;if(_panelRescanCounter>=PANEL_RESCAN_INTERVAL_TICKS){_panelRescanCounter=0;ScanDisplayPanels();}RenderDisplays();Echo($"OrderStation v{VERSION} | {stationId}");Echo($"PMV4: {(pmv4Connected ? "Connected" : "Disconnected")} | Supply: {supplyStation}");Echo($"Surplus: {pmv4Surplus.Count} items | Deficits: {pmv4Deficit.Count} items");Echo($"Exchanges: {activeExchanges.Count} | Connectors: {samConnectors.Count}");Echo($"Transfer: {(transferPhase == PHASE_NONE ? "idle" : transferPhase == PHASE_PULLING ? "pulling" : "pushing")}");if(outOfStock)Echo("OUT OF STOCK");if(requestPending)Echo($"Request pending ({outOfStockCounter}/{OUT_OF_STOCK_TICKS})");
int tn=(int)(reportInterval*0.6);if(tn<1)tn=1;Echo($"Next report: {(int)((tn - reportTickCounter) / 0.6)}s");Echo($"Last eval: {_lastEvalResult}");Echo($"Dock now: {DockedDroneNames()}");if(!string.IsNullOrEmpty(_lastArrivalDbg))Echo($"Arrival: {_lastArrivalDbg}");if(!string.IsNullOrEmpty(_lastReturnDbg))Echo($"Return: {_lastReturnDbg}");if(!string.IsNullOrEmpty(_exchNewDbg))Echo($"ExchNew: {_exchNewDbg}");if(!string.IsNullOrEmpty(_exchDbg))Echo($"ExchRem: {_exchDbg}");}}void FindPMV4(){pmv4PB=null;var pbs=new List<IMyProgrammableBlock>();GridTerminalSystem.GetBlocksOfType(pbs,pb=>pb.CubeGrid==Me.CubeGrid&&pb.CustomData.Contains("[ProductionManagementv3]"));if(pbs.Count>0)pmv4PB=pbs[0];}void ProcessPMV4Data(){string myGrid=Me.CubeGrid.EntityId.ToString();while(pmv4InvListener.HasPendingMessage){var msg=pmv4InvListener.AcceptMessage();var d=msg.Data as string;if(d==null)continue;var parts=d.Split('|');if(parts.Length<2)continue;string type=parts[0];string gridId=parts[1];if(gridId!=myGrid)continue;Dictionary<string,int>target=null;if(type=="INVENTORY")target=pmv4Inventory;else if(type=="SURPLUS")target=pmv4Surplus;else if(type=="DEFICIT")target=pmv4Deficit;else continue;target.Clear();for(int i=2;i<parts.Length;i++){int ci=parts[i].IndexOf(':');if(ci<0)continue;string item=parts[i].Substring(0,ci);int qty;if(int.TryParse(parts[i].Substring(ci+1),out qty))target[item]=qty;}pmv4Connected=true;pmv4StaleCounter=0;}}void ProcessSAMBroadcasts(){while(samListener.HasPendingMessage){var msg=samListener.AcceptMessage();var d=msg.Data as string;if(d==null)continue;var q=new Queue<string>(d.Split(new[]{"\n"},StringSplitOptions.None));if(q.Count<5)continue;string version=q.Dequeue();bool isV2V=version=="SAMv2V";if(!isV2V&&version!="SAMv2")continue;if(isV2V)q.Dequeue();long gridId;if(!long.TryParse(q.Dequeue(),out gridId))continue;if(gridId!=myGridEntityId)continue;string stationName=q.Dequeue();if(!isV2V)q.Dequeue();int connCount;if(!int.TryParse(q.Dequeue(),out connCount))continue;samConnectors.Clear();samConnectorIds.Clear();for(int i=0;i<connCount&&q.Count>=2;i++){long connId;long.TryParse(q.Dequeue(),out connId);string connName=q.Dequeue();if(connName.Contains("|H"))connName=connName.Replace("|H","");samConnectors.Add(connName);samConnectorIds.Add(connId);for(int s=0;s<9&&q.Count>0;s++)q.Dequeue();if(isV2V&&q.Count>0)q.Dequeue();int guideCount;if(q.Count>0&&int.TryParse(q.Peek(),out guideCount)){q.Dequeue();for(int g=0;g<guideCount;g++)for(int s=0;s<6&&q.Count>0;s++)q.Dequeue();}}}}string PickAvailableConnector(){for(int i=0;i<samConnectors.Count;i++){string name=samConnectors[i];if(connectorReservations.ContainsKey(name))continue;var block=GridTerminalSystem.GetBlockWithId(samConnectorIds[i])as IMyShipConnector;if(block==null)continue;if(block.Status==MyShipConnectorStatus.Connected)continue;return name;}return"";}void ReserveConnector(string connectorName,string droneId){if(!string.IsNullOrEmpty(connectorName))connectorReservations[connectorName]=droneId;}void ReleaseConnector(string connectorName){if(!string.IsNullOrEmpty(connectorName))connectorReservations.Remove(connectorName);}string _lastEvalResult="";string _lastReturnDbg="";string _lastArrivalDbg="";string _exchDbg="";string _exchNewDbg="";void EvaluateAndSendRequest(bool isManual){if(string.IsNullOrEmpty(supplyStation)||supplyStation=="CHANGE_ME"){_lastEvalResult="no supply station";return;}if(activeExchanges.Count>0){_lastEvalResult="mission in progress";return;}if(currentTick<missionCooldownEndTick){_lastEvalResult="drone returning";return;}var wantItems=new Dictionary<string,int>();if(isManual){foreach(var kv in manualOrders)wantItems[kv.Key]=kv.Value;}else{foreach(var kv in pmv4Deficit){int effective=kv.Value;foreach(var ex in activeExchanges){int inTransit;if(ex.WillBring.TryGetValue(kv.Key,out inTransit))effective-=inTransit;}if(effective>0&&MatchesCategory(kv.Key,requestCategories))wantItems[kv.Key]=effective;}}var offerItems=new Dictionary<string,int>();if(explicitExports.Count>0){foreach(var kv in explicitExports)if(MatchesCategory(kv.Key,exportCategories))offerItems[kv.Key]=kv.Value;
}else if(exportSurplus){foreach(var kv in pmv4Surplus){if(!MatchesCategory(kv.Key,exportCategories))continue;int unreserved=kv.Value;foreach(var ex in activeExchanges){int reserved;if(ex.WillCollect.TryGetValue(kv.Key,out reserved))unreserved-=reserved;}if(unreserved>0)offerItems[kv.Key]=unreserved;}}if(!isManual){int totalOffer=0;foreach(var kv in offerItems)totalOffer+=kv.Value;int totalWant=0;foreach(var kv in wantItems)totalWant+=kv.Value;if(totalOffer<reportThreshold&&totalWant<reportThreshold){_lastEvalResult=$"below threshold: offer={totalOffer} want={totalWant} thresh={reportThreshold}";return;}}string connName=PickAvailableConnector();if(string.IsNullOrEmpty(connName)&&(wantItems.Count>0||offerItems.Count>0)){_lastEvalResult="no connector available";return;}var pos=Me.GetPosition();string gps=$"{pos.X:F1}:{pos.Y:F1}:{pos.Z:F1}";string wants=FormatItemList(wantItems);string offers=FormatItemList(offerItems);string flags="";if(pmv4Deficit.Count>3){var projectors=new List<IMyProjector>();GridTerminalSystem.GetBlocksOfType(projectors,p=>p.CubeGrid==Me.CubeGrid&&p.IsProjecting&&p.RemainingBlocks>0);if(projectors.Count>0)flags="SURGE";}string locTagsCsv=locationTags.Count>0?string.Join(",",locationTags):"";string message=$"EXCHANGE_REQUEST|{stationId}|{supplyStation}|{gps}|{wants}|{offers}|{flags}|{connName}|{locTagsCsv}";IGC.SendBroadcastMessage(CH_EXCHANGE_REQ,message);_lastEvalResult=$"SENT: want={wantItems.Count} offer={offerItems.Count} conn={connName}";pendingConnector=connName;requestPending=true;outOfStock=false;outOfStockCounter=0;lastRequestTick=currentTick;}int ExchangeTimeoutTicks(int etaSeconds){int ticks=(int)((etaSeconds*4+180)*0.6);return ticks<180?180:ticks;}void ProcessExchangeAccepted(){while(exchangeAccListener.HasPendingMessage){var msg=exchangeAccListener.AcceptMessage();var d=msg.Data as string;if(d==null)continue;var parts=d.Split('|');if(parts.Length<7||parts[0]!="EXCHANGE_ACCEPTED")continue;if(parts[1]!=stationId)continue;if(parts[2]!=supplyStation)continue;var ex=new ActiveExchange();ex.SupplyStationId=parts[2];ex.DroneId=parts[3];ex.WillBring=ParseItemList(parts[4]);ex.WillCollect=ParseItemList(parts[5]);int eta;int.TryParse(parts[6],out eta);ex.ETASeconds=eta;ex.AcceptedTick=currentTick;ex.TimeoutTicks=ExchangeTimeoutTicks(eta);if(parts.Length>=8){double cap;if(double.TryParse(parts[7],out cap))ex.DroneCapacityL=cap;}ex.ConnectorName=pendingConnector;ReserveConnector(pendingConnector,ex.DroneId);activeExchanges.Add(ex);_exchNewDbg=$"CREATED drone={ex.DroneId} eta={eta}s timeout={ex.TimeoutTicks}c atick={ex.AcceptedTick} ctick={currentTick}";requestPending=false;pendingConnector="";outOfStock=false;lastRejectReason="";PersistState();}}void ProcessExchangeRejected(){while(exchangeRejListener.HasPendingMessage){var msg=exchangeRejListener.AcceptMessage();var d=msg.Data as string;if(d==null)continue;var parts=d.Split('|');if(parts.Length<3||parts[0]!="EXCHANGE_REJECTED")continue;if(parts[1]!=stationId)continue;lastRejectReason=parts[2];requestPending=false;outOfStockCounter=0;}}void ProcessSupplyInventory(){while(supplyInvListener.HasPendingMessage){var msg=supplyInvListener.AcceptMessage();var d=msg.Data as string;if(d==null)continue;var parts=d.Split('|');if(parts.Length<2||parts[0]!="SS_INVENTORY")continue;if(parts[1]!=supplyStation)continue;supplyInventory.Clear();for(int i=2;i<parts.Length;i++){int ci=parts[i].IndexOf(':');if(ci<0)continue;string item=parts[i].Substring(0,ci);int qty;if(int.TryParse(parts[i].Substring(ci+1),out qty))supplyInventory[item]=qty;}}}void ProcessMissionComplete(){while(missionCompleteListener.HasPendingMessage){var msg=missionCompleteListener.AcceptMessage();var d=msg.Data as string;if(d==null)continue;var parts=d.Split('|');if(parts.Length<2||parts[0]!="MISSION_COMPLETE")continue;if(parts[1]!=stationId)continue;missionCooldownEndTick=0;lastRejectReason="";}}void CheckReservationTimeouts(){for(int i=activeExchanges.Count-1;i>=0;i--){var ex=activeExchanges[i];if(currentTick-ex.AcceptedTick>ex.TimeoutTicks){_exchDbg=$"TIMEOUT drone={ex.DroneId} elapsed={currentTick - ex.AcceptedTick}c timeout={ex.TimeoutTicks}c";
ReleaseConnector(ex.ConnectorName);if(transferPhase!=PHASE_NONE&&(ex.DroneGridName==transferGridName||ex.DroneId==transferGridName)){transferPhase=PHASE_NONE;transferGridName="";}activeExchanges.RemoveAt(i);PersistState();}}}bool IsGridDockedHere(string gridName){var connectors=new List<IMyShipConnector>();GridTerminalSystem.GetBlocksOfType(connectors,c=>c.CubeGrid==Me.CubeGrid&&c.Status==MyShipConnectorStatus.Connected&&c.OtherConnector!=null&&c.OtherConnector.CubeGrid.CustomName==gridName);return connectors.Count>0;}string DockedDroneNames(){var cons=new List<IMyShipConnector>();GridTerminalSystem.GetBlocksOfType(cons,c=>c.CubeGrid==Me.CubeGrid&&c.Status==MyShipConnectorStatus.Connected&&c.OtherConnector!=null);if(cons.Count==0)return"none";var sb=new StringBuilder();foreach(var c in cons){if(sb.Length>0)sb.Append(", ");sb.Append(c.OtherConnector.CubeGrid.CustomName);}return sb.ToString();}void ProcessDroneArrived(){while(droneArrivedListener.HasPendingMessage){var msg=droneArrivedListener.AcceptMessage();var d=msg.Data as string;if(d==null)continue;var parts=d.Split('|');if(parts.Length<3||parts[0]!="ARRIVED")continue;string droneId=parts[1];string gridName=parts[2];ActiveExchange match=null;foreach(var ex in activeExchanges){if(ex.DroneId==droneId){match=ex;break;}}bool dockedHere=IsGridDockedHere(gridName);_lastArrivalDbg=$"id={droneId} grid={gridName} here={dockedHere} match={(match != null)} ex={activeExchanges.Count}";if(!dockedHere)continue;if(transferPhase!=PHASE_NONE)continue;transferGridName=gridName;transferHasMatch=match!=null;transferCapacityL=match!=null?match.DroneCapacityL:999999;transferStartTick=currentTick;transferOffer=match!=null?new Dictionary<string,int>(match.WillCollect):new Dictionary<string,int>();transferManifest="";transferPhase=PHASE_PULLING;IGC.SendBroadcastMessage(CH_PMV4_CMD,$"PULL|{gridName}");PersistState();}}void CheckDockedArrival(){if(transferPhase!=PHASE_NONE)return;foreach(var ex in activeExchanges){if(string.IsNullOrEmpty(ex.ConnectorName))continue;int idx=samConnectors.IndexOf(ex.ConnectorName);if(idx<0||idx>=samConnectorIds.Count)continue;var conn=GridTerminalSystem.GetBlockWithId(samConnectorIds[idx])as IMyShipConnector;if(conn==null||conn.Status!=MyShipConnectorStatus.Connected||conn.OtherConnector==null)continue;string gridName=conn.OtherConnector.CubeGrid.CustomName;ex.DroneGridName=gridName;transferGridName=gridName;transferHasMatch=true;transferCapacityL=ex.DroneCapacityL;transferStartTick=currentTick;transferOffer=new Dictionary<string,int>(ex.WillCollect);transferManifest="";transferPhase=PHASE_PULLING;_lastArrivalDbg=$"SWEEP conn={ex.ConnectorName} grid={gridName}";IGC.SendBroadcastMessage(CH_PMV4_CMD,$"PULL|{gridName}");PersistState();break;}}void ProcessCargoStatus(){while(pmv4StatusListener.HasPendingMessage){var msg=pmv4StatusListener.AcceptMessage();var d=msg.Data as string;if(d==null)continue;var parts=d.Split('|');if(parts.Length<2)continue;string cmd=parts[0];string gridName=parts[1];if(gridName!=transferGridName)continue;if(cmd=="PULL_COMPLETE"&&transferPhase==PHASE_PULLING){if(transferOffer.Count>0){transferManifest=BuildReturnManifest();if(!string.IsNullOrEmpty(transferManifest)){transferPhase=PHASE_PUSHING;IGC.SendBroadcastMessage(CH_PMV4_CMD,$"PUSH|{transferGridName}|{transferManifest}");}else{FinishTransfer();}}else if(transferHasMatch&&(exportSurplus||explicitExports.Count>0)){_lastReturnDbg="PUSH_SURPLUS (offer empty, matched)";transferPhase=PHASE_PUSHING;IGC.SendBroadcastMessage(CH_PMV4_CMD,$"PUSH_SURPLUS|{transferGridName}|{transferCapacityL:F0}");}else{_lastReturnDbg=$"no-load (offer={transferOffer.Count} match={transferHasMatch})";FinishTransfer();}PersistState();}else if(cmd=="PUSH_COMPLETE"&&transferPhase==PHASE_PUSHING){FinishTransfer();PersistState();}else if(cmd=="BUSY"){}}}void FinishTransfer(){IGC.SendBroadcastMessage(CH_PMV4_STAT,$"TRANSFER_COMPLETE|{transferGridName}");int returnEtaSeconds=0;for(int i=activeExchanges.Count-1;i>=0;i--){if(activeExchanges[i].DroneGridName==transferGridName||activeExchanges[i].DroneId==transferGridName){_exchDbg=$"FINISH-REMOVED drone={activeExchanges[i].DroneId} grid={transferGridName}";
