if(firstReal>=end||lines[firstReal].Col==_theme.LBL)repeatHeader=false;}}_renderTick++;int sA=254+_renderTick/5%2;float cx=vp.X+surfSize.X*0.5f;float rightX=vp.X+surfSize.X-pad;float maxY=vp.Y+surfSize.Y-pad;var frame=surface.DrawFrame();float contentY=topY;if(repeatHeader){frame.Add(Rect(new Vector2(cx,contentY+lineH*0.5f),new Vector2(surfSize.X,lineH),SaltColor(new Color(sectionHeader.Col.R,sectionHeader.Col.G,sectionHeader.Col.B,210),sA)));frame.Add(Txt(sectionHeader.Text,new Vector2(leftX,contentY),SaltColor(new Color(20,15,5),sA),fontSize));contentY+=lineH;}for(int l=lineIdx;l<end;l++){float y=contentY+(l-lineIdx)*lineH;if(repeatHeader)y+=lineH;if(y>maxY)break;var line=lines[l];if(line.IsBanner){float bh=lineH*2.0f;frame.Add(Rect(new Vector2(cx,y+bh*0.5f),new Vector2(surfSize.X,bh),SaltColor(new Color(8,25,38),sA)));frame.Add(Rect(new Vector2(cx,y+1f),new Vector2(surfSize.X,2f),SaltColor(_theme.HDR,sA)));frame.Add(Rect(new Vector2(cx,y+bh-1f),new Vector2(surfSize.X,2f),SaltColor(_theme.HDR,sA)));frame.Add(Rect(new Vector2(vp.X+4f,y+bh*0.5f),new Vector2(8f,bh),SaltColor(_theme.HDR,sA)));frame.Add(Rect(new Vector2(vp.X+surfSize.X-4f,y+bh*0.5f),new Vector2(8f,bh),SaltColor(_theme.HDR,sA)));frame.Add(Txt(line.Text,new Vector2(cx,y+lineH*0.1f),SaltColor(Color.White,sA),fontSize*1.1f,TextAlignment.CENTER));if(line.RightText.Length>0)frame.Add(Txt(line.RightText,new Vector2(rightX-8f,y+lineH*0.1f),SaltColor(_theme.DIM,sA),fontSize*0.85f,TextAlignment.RIGHT));continue;}if(line.IsSep){frame.Add(Rect(new Vector2(cx,y+lineH*0.5f),new Vector2(surfSize.X-16f,sepH),SaltColor(new Color(55,55,65),sA)));continue;}if(line.Text.Length==0)continue;bool isHeader=line.Col==_theme.LBL;if(isHeader){frame.Add(Rect(new Vector2(cx,y+lineH*0.5f),new Vector2(surfSize.X,lineH),SaltColor(new Color(line.Col.R,line.Col.G,line.Col.B,210),sA)));}float textX=leftX;if(line.DotCol.A>0){frame.Add(new MySprite(SpriteType.TEXTURE,"Circle",new Vector2(leftX+dotR,y+lineH*0.5f),new Vector2(dotR*2f,dotR*2f),SaltColor(line.DotCol,sA)));textX=leftX+dotR*2f+3f;}Color textCol=isHeader?new Color(20,15,5):line.Col;frame.Add(Txt(line.Text,new Vector2(textX,y),SaltColor(textCol,sA),fontSize));if(line.RightText.Length>0&&!isHeader){frame.Add(Txt(line.RightText,new Vector2(rightX,y),SaltColor(line.Col,sA),fontSize,TextAlignment.RIGHT));}}frame.Dispose();lineIdx=end;if(lineIdx>=total){for(int q=p+1;q<panels.Count;q++){panels[q].ContentType=ContentType.SCRIPT;panels[q].Script="";using(panels[q].DrawFrame()){}}break;}}}static bool HasTag(string text,string tag){int pos=text.IndexOf(tag);while(pos>=0){int end=pos+tag.Length;bool validEnd=end>=text.Length||!char.IsLetterOrDigit(text[end]);bool validStart=pos==0||!char.IsLetterOrDigit(text[pos-1]);if(validStart&&validEnd)return true;pos=text.IndexOf(tag,pos+1);}return false;}static bool CustomDataHasTag(string customData,string tag){foreach(var line in customData.Split('\n')){var t=line.Trim();if(t==tag)return true;if(t.Length>tag.Length&&t.StartsWith(tag)&&t[tag.Length]==':')return true;}return false;}List<IMyTextSurface>GetDisplaySurfaces(string tag){var entries=new List<KeyValuePair<string,IMyTextSurface>>();var panels=new List<IMyTextPanel>();GridTerminalSystem.GetBlocksOfType(panels,p=>HasTag(p.CustomName,tag)||CustomDataHasTag(p.CustomData,tag));foreach(var p in panels)entries.Add(new KeyValuePair<string,IMyTextSurface>(p.CustomName,p));var allBlocks=new List<IMyTerminalBlock>();GridTerminalSystem.GetBlocksOfType(allBlocks,b=>!(b is IMyTextPanel)&&b is IMyTextSurfaceProvider&&CustomDataHasTag(b.CustomData,tag));foreach(var block in allBlocks){var provider=(IMyTextSurfaceProvider)block;int idx=ParseSurfaceIndex(block.CustomData,tag);if(idx>=0&&idx<provider.SurfaceCount)entries.Add(new KeyValuePair<string,IMyTextSurface>(block.CustomName,provider.GetSurface(idx)));}entries.Sort((a,b)=>string.Compare(a.Key,b.Key));var result=new List<IMyTextSurface>();foreach(var entry in entries)result.Add(entry.Value);return result;}int ParseSurfaceIndex(string customData,string tag){foreach(var line in customData.Split('\n')){var trimmed=line.Trim();
if(trimmed==tag)return 0;if(trimmed.Length>tag.Length&&trimmed.StartsWith(tag)&&trimmed[tag.Length]==':'){int idx;if(int.TryParse(trimmed.Substring(tag.Length+1).Trim(),out idx))return idx;return 0;}}return 0;}void ScanDisplayPanels(){foreach(var grp in _displayGroups){grp.Panels.Clear();var surfaces=GetDisplaySurfaces(grp.Tag);foreach(var surf in surfaces){surf.ContentType=ContentType.SCRIPT;surf.Script="";surf.ScriptBackgroundColor=_theme.BG;surf.Font="Monospace";surf.FontSize=0.5f;grp.Panels.Add(surf);}}}string FormatAmount(int value){if(value>=1000000){double m=value/1000000.0;return m%1==0?$"{(int)m}m":$"{m:0.#}m";}if(value>=1000){double k=value/1000.0;return k%1==0?$"{(int)k}k":$"{k:0.#}k";}return value.ToString();}bool MatchesCategory(string itemName,HashSet<string>categories){if(categories.Count==0)return true;int dot=itemName.IndexOf('.');string cat=dot>=0?itemName.Substring(0,dot):itemName;return categories.Contains(cat);}string ShortName(string fullName){int dot=fullName.IndexOf('.');return dot>=0?fullName.Substring(dot+1):fullName;}string FormatItemList(Dictionary<string,int>items){if(items==null||items.Count==0)return"";var parts=new List<string>();foreach(var kv in items)parts.Add($"{kv.Key}:{kv.Value}");return string.Join(",",parts);}Dictionary<string,int>ParseItemList(string data){var result=new Dictionary<string,int>();if(string.IsNullOrEmpty(data))return result;foreach(var entry in data.Split(',')){int ci=entry.IndexOf(':');if(ci<0)continue;string item=entry.Substring(0,ci);int qty;if(int.TryParse(entry.Substring(ci+1),out qty))result[item]=qty;}return result;}
